// Editor UI: the Outfit font and Pixelify Sans for titles (both SIL Open Font License 1.1,
// resources/fonts/; compiled in from src/font_outfit.h and src/font_pixelify.h, generated by
// tools/embed_font.py, so nothing is read from disk), the type scale, colour tokens and the
// helpers every editor overlay draws with. The look: docs/ui-design.md.
//
// Every size of the type scale in both weights is rasterised once (bitmap glyphs at the exact
// pixel size they are drawn at: sharper than one scaled SDF font at 14-24 px, and no shader)
// and packed into ONE atlas texture, which also holds a white block that becomes raylib's
// shapes texture. Text and rectangles then share a texture, so the whole overlay stays in one
// batch instead of flushing at every switch between a panel and its text (it is drawn every
// frame, also over a reused frame that otherwise costs ~0.2 ms). Text is drawn at integer
// positions and the native size, so the bilinear filter samples texel centres. Rounded corners
// come from the same atlas (anti-aliased discs and rings, drawn as nine-slices): raylib's
// DrawRectangleRounded* emit dozens of triangles each and switch the batch's draw mode, which
// made the overlay cost ~0.13 ms more per frame (measured with ~60 key caps on screen). Key
// caps, the most frequent shape, are one baked sprite per line size (border and fill in one),
// drawn as a 3-slice: 3 quads per cap instead of ~15. A panel's soft halo is one baked sprite
// drawn as 8 quads around it (a CSS box-shadow without a blur pass). Text is laid out here, the way raylib's
// DrawTextEx / MeasureTextEx do it, but with a codepoint -> glyph table instead of raylib's
// GetGlyphIndex, a linear search over the ~290 glyphs for every character (0.04-0.05 ms per
// frame of the HUD); the quads are the same.
#include "ui.h"
#include "font_outfit.h"
#include "font_pixelify.h"
#include <math.h>

// Pixel size raylib (stb_truetype) rasterises at for an em size: stb scales ascent - descent
// to the pixel height, and Outfit's are 1000 and -260 units per 1000-unit em
#define EM_TO_PX    1.26f
#define ATLAS_W     1024
#define ATLAS_PAD   2       // transparent gap between glyphs (no bilinear bleed)
#define WHITE_SIZE  4       // white block at 0,0; the shapes rectangle is its inner 2 x 2

static const int SIZES[] = { UI_XS, UI_S, UI_M, UI_L, UI_XL };
// Corner radii in the atlas: panels, key caps and small boxes, the tags, a tag's dark rim
static const int CORNER_R[] = { UI_RADIUS, UI_CAP_R, UI_PILL_H / 2, UI_PILL_H / 2 + 1 };
#define CORNER_COUNT ((int)(sizeof(CORNER_R) / sizeof(CORNER_R[0])))
#define SIZE_COUNT ((int)(sizeof(SIZES) / sizeof(SIZES[0])))
#define FACE_COUNT (2 * SIZE_COUNT)     // [bold * SIZE_COUNT + size index]
#define FACE_PIXEL FACE_COUNT           // the Pixelify face (titles), after the Outfit ones
#define FACE_ALL (FACE_COUNT + 1)
// Pixelify Sans draws its glyphs on a grid of ~91 of 1000 units (about 1/11 em, the cells
// ~101 units wide, so a little overlap) that no integer pixel height of stb_truetype matches
// (it scales ascender - descender, 1200 units, to the pixel height). Rasterised at 13 px the
// cell is 0.985 px: thresholded at half coverage each cell becomes one whole pixel, and the
// glyph is then enlarged PIXEL_SCALE x with nearest sampling into the atlas: hard pixel edges,
// integer advances, no blur. Only this one size exists.
#define PIXEL_RASTER 13
#define PIXEL_SCALE  3
// The halo sprite: a rounded rect of UI_RADIUS with a soft dark falloff outside it (CSS
// box-shadow 0 0 10px 1px: a gaussian of sigma 5 px, 1 px spread), drawn as a 9-slice around
// a panel; nothing under the panel itself
#define HALO_SIGMA  5.0f
#define HALO_SPREAD 1.0f
#define HALO_E      (UI_HALO + UI_RADIUS)   // a corner of the sprite; its middle row / column is 1 px

static struct {
    bool tried, ok;
    Font face[FACE_ALL];
    Rectangle disc[CORNER_COUNT], ring[CORNER_COUNT];   // 2r x 2r, filled / 1 px outline
    Rectangle cap[SIZE_COUNT];      // key cap of a line of each size: (2 UI_CAP_R + 3) x CapHeight
    Rectangle halo;                 // (2 HALO_E + 1) square
    short *glyphOf[FACE_ALL];       // codepoint 0..glyphMax -> glyph index, as GetGlyphIndex gives it
    int glyphMax[FACE_ALL];
    Texture2D atlas;
    Texture2D oldShapes;    // raylib's shapes texture before ours (restored by UiClose)
    Rectangle oldShapesRec;
} ui;

Color UiAlpha(Color c, float a) { c.a = (unsigned char)(c.a * fminf(fmaxf(a, 0.0f), 1.0f) + 0.5f); return c; }
#define Mul UiAlpha

static int PixelSize(int size) { return (int)(size * EM_TO_PX + 0.5f); }
static int CapMiddle(int size);
static int CapHeight(int lineSize) { return PixelSize(lineSize) - 4; }  // key cap box in a line

static void FreeFaces(void)
{
    for (int i = 0; i < FACE_ALL; i++) {
        if (ui.face[i].glyphs) UnloadFontData(ui.face[i].glyphs, ui.face[i].glyphCount);
        free(ui.face[i].recs);
        free(ui.glyphOf[i]);
        ui.glyphOf[i] = NULL;
    }
    memset(ui.face, 0, sizeof(ui.face));
}

// The glyph table of face i: the first glyph with the codepoint, else raylib's fallback ('?')
static bool BuildGlyphTable(int i)
{
    const Font *f = &ui.face[i];
    int max = 0;
    for (int g = 0; g < f->glyphCount; g++)
        if (f->glyphs[g].value > max) max = f->glyphs[g].value;
    ui.glyphOf[i] = malloc(sizeof(short) * (size_t)(max + 1));
    if (!ui.glyphOf[i] || f->glyphCount > 32767) return false;
    short fallback = (short)GetGlyphIndex(*f, -1);
    for (int c = 0; c <= max; c++) ui.glyphOf[i][c] = fallback;
    for (int g = f->glyphCount - 1; g >= 0; g--)
        if (f->glyphs[g].value >= 0) ui.glyphOf[i][f->glyphs[g].value] = (short)g;
    ui.glyphMax[i] = max;
    return true;
}

static void Load(void)
{
    ui.tried = true;
    if (!IsWindowReady()) return;
    // Rasterise every face (glyph images, then packed below)
    for (int i = 0; i < FACE_COUNT; i++) {
        bool bold = i >= SIZE_COUNT;
        Font *f = &ui.face[i];
        f->baseSize = PixelSize(SIZES[i % SIZE_COUNT]);
        f->glyphCount = bold ? OUTFIT_SEMIBOLD_CODEPOINT_COUNT : OUTFIT_REGULAR_CODEPOINT_COUNT;
        // (raylib takes non-const codepoints but only reads them)
        f->glyphs = LoadFontData(bold ? OUTFIT_SEMIBOLD : OUTFIT_REGULAR, bold ? OUTFIT_SEMIBOLD_SIZE : OUTFIT_REGULAR_SIZE,
                                 f->baseSize, (int *)(bold ? OUTFIT_SEMIBOLD_CODEPOINTS : OUTFIT_REGULAR_CODEPOINTS),
                                 f->glyphCount, FONT_DEFAULT);
        f->recs = calloc((size_t)f->glyphCount, sizeof(Rectangle));
        if (!f->glyphs || !f->recs || !BuildGlyphTable(i)) {
            TraceLog(LOG_WARNING, "monolith: cannot load the UI font, using raylib's default font");
            FreeFaces();
            return;
        }
    }
    {
        Font *f = &ui.face[FACE_PIXEL];
        f->glyphCount = PIXELIFY_REGULAR_CODEPOINT_COUNT;
        f->glyphs = LoadFontData(PIXELIFY_REGULAR, PIXELIFY_REGULAR_SIZE, PIXEL_RASTER, (int *)PIXELIFY_REGULAR_CODEPOINTS,
                                 f->glyphCount, FONT_DEFAULT);
        f->recs = calloc((size_t)f->glyphCount, sizeof(Rectangle));
        if (!f->glyphs || !f->recs || !BuildGlyphTable(FACE_PIXEL)) {
            TraceLog(LOG_WARNING, "monolith: cannot load the UI title font, using raylib's default font");
            FreeFaces();
            return;
        }
        // Whole pixels, enlarged: the face's metrics become those of a PIXEL_SCALE x font
        f->baseSize = PIXEL_RASTER * PIXEL_SCALE;
        for (int g = 0; g < f->glyphCount; g++) {
            GlyphInfo *gl = &f->glyphs[g];
            Image im = gl->image, big = { 0 };
            if (im.data && im.width > 0 && im.height > 0) {
                big = (Image){ .width = im.width * PIXEL_SCALE, .height = im.height * PIXEL_SCALE, .mipmaps = 1,
                               .format = PIXELFORMAT_UNCOMPRESSED_GRAYSCALE };
                big.data = malloc((size_t)big.width * big.height);
                if (!big.data) { FreeFaces(); return; }
                const unsigned char *src = im.data;
                unsigned char *dst = big.data;
                for (int yy = 0; yy < big.height; yy++)
                    for (int xx = 0; xx < big.width; xx++)
                        dst[yy * big.width + xx] = src[(yy / PIXEL_SCALE) * im.width + xx / PIXEL_SCALE] >= 128 ? 255 : 0;
            }
            UnloadImage(im);
            gl->image = big;
            gl->offsetX *= PIXEL_SCALE;
            gl->offsetY *= PIXEL_SCALE;
            gl->advanceX *= PIXEL_SCALE;
        }
    }
    // Shelf packing, left to right: the white block, the corner discs and rings, the glyphs
    int x = WHITE_SIZE + ATLAS_PAD, y = 0, rowH = WHITE_SIZE;
    for (int k = 0; k < CORNER_COUNT; k++) {
        float d = 2.0f * CORNER_R[k];
        ui.disc[k] = (Rectangle){ (float)x, 0, d, d };
        ui.ring[k] = (Rectangle){ (float)x + d + ATLAS_PAD, 0, d, d };
        x += 2 * ((int)d + ATLAS_PAD);
        if ((int)d > rowH) rowH = (int)d;
    }
    for (int i = 0; i < SIZE_COUNT; i++) {
        int ch = CapHeight(SIZES[i]);
        ui.cap[i] = (Rectangle){ (float)x, 0, 2 * UI_CAP_R + 3, (float)ch };
        x += 2 * UI_CAP_R + 3 + ATLAS_PAD;
        if (ch > rowH) rowH = ch;
    }
    ui.halo = (Rectangle){ (float)x, 0, 2 * HALO_E + 1, 2 * HALO_E + 1 };
    x += 2 * HALO_E + 1 + ATLAS_PAD;
    if (2 * HALO_E + 1 > rowH) rowH = 2 * HALO_E + 1;
    for (int i = 0; i < FACE_ALL; i++)
        for (int g = 0; g < ui.face[i].glyphCount; g++) {
            Image im = ui.face[i].glyphs[g].image;
            if (x + im.width > ATLAS_W) { x = 0; y += rowH + ATLAS_PAD; rowH = 0; }
            ui.face[i].recs[g] = (Rectangle){ (float)x, (float)y, (float)im.width, (float)im.height };
            x += im.width + ATLAS_PAD;
            if (im.height > rowH) rowH = im.height;
        }
    int h = y + rowH;
    unsigned char *px = calloc((size_t)ATLAS_W * h, 2);    // grey + alpha
    if (!px) { FreeFaces(); return; }
    for (int i = 0; i < ATLAS_W * h; i++) px[2 * i] = 255;
    for (int yy = 0; yy < WHITE_SIZE; yy++)
        for (int xx = 0; xx < WHITE_SIZE; xx++) px[2 * (yy * ATLAS_W + xx) + 1] = 255;
    for (int k = 0; k < CORNER_COUNT; k++) {
        // Coverage of each pixel by the disc of radius r around the sprite's centre (and by
        // the 1 px ring at its edge)
        float r = (float)CORNER_R[k];
        for (int yy = 0; yy < 2 * CORNER_R[k]; yy++)
            for (int xx = 0; xx < 2 * CORNER_R[k]; xx++) {
                float dist = hypotf(xx + 0.5f - r, yy + 0.5f - r);
                float outer = fminf(fmaxf(r - dist + 0.5f, 0.0f), 1.0f);
                float inner = fminf(fmaxf(r - 1.0f - dist + 0.5f, 0.0f), 1.0f);
                px[2 * (yy * ATLAS_W + (int)ui.disc[k].x + xx) + 1] = (unsigned char)(outer * 255.0f + 0.5f);
                px[2 * (yy * ATLAS_W + (int)ui.ring[k].x + xx) + 1] = (unsigned char)((outer - inner) * 255.0f + 0.5f);
            }
    }
    {
        // The halo: outside the rounded rect only, CSS's blurred shadow (half the erfc of the
        // distance), times the rect's anti-aliased outside coverage
        Rectangle c = ui.halo;
        float hw = c.width / 2.0f, r = (float)UI_RADIUS, half = hw - UI_HALO;
        for (int yy = 0; yy < (int)c.height; yy++)
            for (int xx = 0; xx < (int)c.width; xx++) {
                float qx = fabsf(xx + 0.5f - hw) - (half - r), qy = fabsf(yy + 0.5f - hw) - (half - r);
                float dist = hypotf(fmaxf(qx, 0.0f), fmaxf(qy, 0.0f)) + fminf(fmaxf(qx, qy), 0.0f) - r;
                float shadow = 0.5f * erfcf((dist - HALO_SPREAD) / (HALO_SIGMA * 1.41421356f));
                float outside = fminf(fmaxf(dist + 0.5f, 0.0f), 1.0f);
                px[2 * (yy * ATLAS_W + (int)c.x + xx) + 1] = (unsigned char)(shadow * outside * 255.0f + 0.5f);
            }
    }
    for (int i = 0; i < SIZE_COUNT; i++) {
        // A whole key cap: a filled rounded box (signed distance), anti-aliased edge. Its
        // middle columns are straight, so the middle stretches to any width.
        Rectangle c = ui.cap[i];
        float hw = c.width / 2.0f, hh = c.height / 2.0f, r = (float)UI_CAP_R;
        for (int yy = 0; yy < (int)c.height; yy++)
            for (int xx = 0; xx < (int)c.width; xx++) {
                float qx = fabsf(xx + 0.5f - hw) - (hw - r), qy = fabsf(yy + 0.5f - hh) - (hh - r);
                float dist = hypotf(fmaxf(qx, 0.0f), fmaxf(qy, 0.0f)) + fminf(fmaxf(qx, qy), 0.0f) - r;
                float outer = fminf(fmaxf(0.5f - dist, 0.0f), 1.0f);
                px[2 * (yy * ATLAS_W + (int)c.x + xx) + 1] = (unsigned char)(outer * 255.0f + 0.5f);
            }
    }
    for (int i = 0; i < FACE_ALL; i++)
        for (int g = 0; g < ui.face[i].glyphCount; g++) {
            GlyphInfo *gl = &ui.face[i].glyphs[g];
            Rectangle r = ui.face[i].recs[g];
            const unsigned char *src = gl->image.data;   // 8-bit coverage
            if (src && gl->image.format == PIXELFORMAT_UNCOMPRESSED_GRAYSCALE)
                for (int yy = 0; yy < (int)r.height; yy++)
                    for (int xx = 0; xx < (int)r.width; xx++)
                        px[2 * ((int)(r.y + yy) * ATLAS_W + (int)r.x + xx) + 1] = src[yy * gl->image.width + xx];
            UnloadImage(gl->image);     // only the atlas is needed from here
            gl->image = (Image){ 0 };
        }
    Image atlas = { .data = px, .width = ATLAS_W, .height = h, .mipmaps = 1, .format = PIXELFORMAT_UNCOMPRESSED_GRAY_ALPHA };
    ui.atlas = LoadTextureFromImage(atlas);
    free(px);
    if (!ui.atlas.id) { FreeFaces(); return; }
    SetTextureFilter(ui.atlas, TEXTURE_FILTER_BILINEAR);
    for (int i = 0; i < FACE_ALL; i++) ui.face[i].texture = ui.atlas;
    TraceLog(LOG_INFO, "monolith: UI atlas %d x %d", ATLAS_W, h);
    ui.oldShapes = GetShapesTexture();
    ui.oldShapesRec = GetShapesTextureRectangle();
    SetShapesTexture(ui.atlas, (Rectangle){ 1, 1, WHITE_SIZE - 2, WHITE_SIZE - 2 });
    ui.ok = true;
}

void UiClose(void)
{
    if (ui.ok) {
        SetShapesTexture(ui.oldShapes, ui.oldShapesRec);
        UnloadTexture(ui.atlas);
    }
    FreeFaces();
    memset(&ui, 0, sizeof(ui));
}

// Font, pixel size and spacing to draw `size` with (the nearest size of the scale; raylib's
// default font, scaled as DrawText does, if the font could not load: id -1)
typedef struct { Font font; float px, spacing; int id; } Face;

static Face GetFace(int size, bool bold)
{
    if (!ui.tried) Load();
    if (!ui.ok) return (Face){ GetFontDefault(), (float)size, (float)(size / 10), -1 };
    int best = 0;
    for (int i = 1; i < SIZE_COUNT; i++)
        if (abs(SIZES[i] - size) < abs(SIZES[best] - size)) best = i;
    int id = (bold ? SIZE_COUNT : 0) + best;
    Font f = ui.face[id];
    return (Face){ f, SIZES[best] == size ? (float)f.baseSize : (float)PixelSize(size), 0.0f, id };
}

static int GlyphOf(const Face *f, int codepoint)
{
    if (f->id < 0 || codepoint < 0 || codepoint > ui.glyphMax[f->id]) return GetGlyphIndex(f->font, codepoint);
    return ui.glyphOf[f->id][codepoint];
}

Font UiFont(int size, bool bold) { return GetFace(size, bold).font; }

int UiLineHeight(int size) { return (int)GetFace(size, false).px; }

float UiAdvance(int codepoint, int size)
{
    Face f = GetFace(size, false);
    int i = GlyphOf(&f, codepoint);
    float adv = f.font.glyphs[i].advanceX ? (float)f.font.glyphs[i].advanceX : f.font.recs[i].width;
    return adv * f.px / (float)f.font.baseSize + f.spacing;
}

// The title face (its one size), or raylib's font at the same height
static Face PixelFace(void)
{
    if (!ui.tried) Load();
    if (!ui.ok) return (Face){ GetFontDefault(), (float)UI_XL, 2.0f, -1 };
    Font f = ui.face[FACE_PIXEL];
    return (Face){ f, (float)f.baseSize, 0.0f, FACE_PIXEL };
}

// MeasureTextEx's width
static int MeasureFace(Face f, const char *text)
{
    if (f.id < 0) return (int)ceilf(MeasureTextEx(f.font, text, f.px, f.spacing).x);
    if (!text || !text[0]) return 0;
    float width = 0.0f, widest = 0.0f;
    int bytes = 0, mostBytes = 0;
    for (int i = 0; text[i]; ) {
        bytes++;
        int n = 0, cp = GetCodepointNext(&text[i], &n), g = GlyphOf(&f, cp);
        i += n;
        if (cp != '\n') width += f.font.glyphs[g].advanceX > 0 ? f.font.glyphs[g].advanceX : f.font.recs[g].width + f.font.glyphs[g].offsetX;
        else {
            if (widest < width) widest = width;
            bytes = 0;
            width = 0.0f;
        }
        if (mostBytes < bytes) mostBytes = bytes;
    }
    if (widest < width) widest = width;
    return (int)ceilf(widest * (f.px / (float)f.font.baseSize) + (float)((mostBytes - 1) * f.spacing));
}

static int Measure(const char *text, int size, bool bold) { return MeasureFace(GetFace(size, bold), text); }

// DrawTextEx's quads (DrawTextCodepoint for each glyph); text with line breaks goes to raylib,
// which owns the line spacing
static void TextFace(Face f, const char *text, int x, int y, Color c)
{
    if (f.id < 0 || strchr(text, '\n')) {
        DrawTextEx(f.font, text, (Vector2){ (float)x, (float)y }, f.px, f.spacing, c);
        return;
    }
    const Font *F = &f.font;
    float scale = f.px / F->baseSize, pad = (float)F->glyphPadding, offsetX = 0.0f;
    for (int i = 0; text[i]; ) {
        int n = 0, cp = GetCodepointNext(&text[i], &n), g = GlyphOf(&f, cp);
        i += n;
        const GlyphInfo *gl = &F->glyphs[g];
        Rectangle r = F->recs[g];
        if (cp != ' ' && cp != '\t') {
            Rectangle dst = { (float)x + offsetX + gl->offsetX * scale - pad * scale, (float)y + gl->offsetY * scale - pad * scale,
                              (r.width + 2.0f * pad) * scale, (r.height + 2.0f * pad) * scale };
            Rectangle src = { r.x - pad, r.y - pad, r.width + 2.0f * pad, r.height + 2.0f * pad };
            DrawTexturePro(F->texture, src, dst, (Vector2){ 0, 0 }, 0.0f, c);
        }
        offsetX += gl->advanceX == 0 ? r.width * scale + f.spacing : gl->advanceX * scale + f.spacing;
    }
}

static void Text(const char *text, int x, int y, int size, bool bold, Color c) { TextFace(GetFace(size, bold), text, x, y, c); }

int UiMeasure(const char *text, int size) { return Measure(text, size, false); }
int UiMeasureBold(const char *text, int size) { return Measure(text, size, true); }
void UiText(const char *text, int x, int y, int size, Color c) { Text(text, x, y, size, false, c); }
void UiTextBold(const char *text, int x, int y, int size, Color c) { Text(text, x, y, size, true, c); }

void UiTextShadow(const char *text, int x, int y, int size, Color c)
{
    Text(text, x + 1, y + 1, size, false, (Color){ 0, 0, 0, (unsigned char)(c.a / 2) });
    Text(text, x, y, size, false, c);
}

// Rounded rectangle (filled, or its 1 px outline) as a nine-slice: corner quarters from a
// disc or ring in the atlas, the rest plain rectangles, all quads of the atlas texture. The
// radius is cut to half the shorter side and drawn with the nearest one in the atlas.
static void Rounded(Rectangle r, int radius, Color c, bool outline)
{
    float rr = fminf((float)radius, fminf(r.width, r.height) / 2.0f);
    if (r.width <= 0.0f || r.height <= 0.0f) return;
    if (!ui.ok || rr < 1.0f) {
        if (outline) DrawRectangleLinesEx(r, 1.0f, c);
        else DrawRectangleRec(r, c);
        return;
    }
    int k = 0;
    for (int i = 1; i < CORNER_COUNT; i++)
        if (fabsf(CORNER_R[i] - rr) < fabsf(CORNER_R[k] - rr)) k = i;
    Rectangle src = outline ? ui.ring[k] : ui.disc[k];
    float q = (float)CORNER_R[k];
    float x0 = r.x, y0 = r.y, x1 = r.x + r.width - rr, y1 = r.y + r.height - rr;
    DrawTexturePro(ui.atlas, (Rectangle){ src.x, src.y, q, q }, (Rectangle){ x0, y0, rr, rr }, (Vector2){ 0, 0 }, 0.0f, c);
    DrawTexturePro(ui.atlas, (Rectangle){ src.x + q, src.y, q, q }, (Rectangle){ x1, y0, rr, rr }, (Vector2){ 0, 0 }, 0.0f, c);
    DrawTexturePro(ui.atlas, (Rectangle){ src.x, src.y + q, q, q }, (Rectangle){ x0, y1, rr, rr }, (Vector2){ 0, 0 }, 0.0f, c);
    DrawTexturePro(ui.atlas, (Rectangle){ src.x + q, src.y + q, q, q }, (Rectangle){ x1, y1, rr, rr }, (Vector2){ 0, 0 }, 0.0f, c);
    float iw = r.width - 2.0f * rr, ih = r.height - 2.0f * rr;
    if (outline) {
        if (iw > 0.0f) {
            DrawRectangleRec((Rectangle){ x0 + rr, y0, iw, 1.0f }, c);
            DrawRectangleRec((Rectangle){ x0 + rr, r.y + r.height - 1.0f, iw, 1.0f }, c);
        }
        if (ih > 0.0f) {
            DrawRectangleRec((Rectangle){ x0, y0 + rr, 1.0f, ih }, c);
            DrawRectangleRec((Rectangle){ r.x + r.width - 1.0f, y0 + rr, 1.0f, ih }, c);
        }
    } else {
        if (iw > 0.0f) {
            DrawRectangleRec((Rectangle){ x0 + rr, y0, iw, rr }, c);
            DrawRectangleRec((Rectangle){ x0 + rr, y1, iw, rr }, c);
        }
        if (ih > 0.0f) DrawRectangleRec((Rectangle){ x0, y0 + rr, r.width, ih }, c);
    }
}

void UiPanel(Rectangle r, Color fill, Color border)
{
    Rounded(r, UI_RADIUS, fill, false);
    if (border.a) Rounded(r, UI_RADIUS, border, true);
}

void UiHalo(Rectangle r, Color c)
{
    if (!ui.tried) Load();
    if (!ui.ok || r.width < 2 * UI_RADIUS || r.height < 2 * UI_RADIUS) return;
    // 8 quads around r: the sprite's corners at their size, its 1 px middle row / column stretched
    Rectangle s = ui.halo;
    float e = HALO_E, x0 = r.x - UI_HALO, y0 = r.y - UI_HALO;
    float x1 = r.x + r.width + UI_HALO - e, y1 = r.y + r.height + UI_HALO - e;
    float mw = x1 - (x0 + e), mh = y1 - (y0 + e);
    Rectangle src[8] = {
        { s.x, s.y, e, e }, { s.x + e + 1, s.y, e, e }, { s.x, s.y + e + 1, e, e }, { s.x + e + 1, s.y + e + 1, e, e },
        { s.x + e, s.y, 1, e }, { s.x + e, s.y + e + 1, 1, e }, { s.x, s.y + e, e, 1 }, { s.x + e + 1, s.y + e, e, 1 },
    };
    Rectangle dst[8] = {
        { x0, y0, e, e }, { x1, y0, e, e }, { x0, y1, e, e }, { x1, y1, e, e },
        { x0 + e, y0, mw, e }, { x0 + e, y1, mw, e }, { x0, y0 + e, e, mh }, { x1, y0 + e, e, mh },
    };
    for (int i = 0; i < 8; i++)
        if (dst[i].width > 0.0f && dst[i].height > 0.0f)
            DrawTexturePro(ui.atlas, src[i], dst[i], (Vector2){ 0, 0 }, 0.0f, c);
}

void UiSheet(Rectangle r)
{
    UiHalo(r, UI_HALO_C);
    Rounded(r, UI_RADIUS, UI_PANEL, false);
}

void UiTitle(const char *text, int x, int y, Color c)
{
    Face f = PixelFace();
    // the glyphs' cells sit on whole pixels only from a whole-pixel origin
    TextFace(f, text, x, y + (UI_TITLE_H - (int)f.px) / 2, c);
}

int UiTitleWidth(const char *text) { return MeasureFace(PixelFace(), text); }

#define PILL_PAD 8
#define MARK_BAR 2      // the mark's left bar
#define MARK_GAP 6      // bar to text

int UiMarkWidth(const char *text) { return MARK_BAR + MARK_GAP + Measure(text, UI_XS, true); }

int UiMark(const char *text, int x, int y, Color c)
{
    DrawRectangle(x, y + 2, MARK_BAR, UI_PILL_H - 4, c);
    Text(text, x + MARK_BAR + MARK_GAP, y + UI_PILL_H / 2 - CapMiddle(UI_XS), UI_XS, true, c);
    return UiMarkWidth(text);
}

int UiPillWidth(const char *text) { return UiMarkWidth(text); }

int UiPill(const char *text, int x, int y, Color fill, Color ink)
{
    (void)ink;
    return UiMark(text, x, y, (Color){ fill.r, fill.g, fill.b, 255 });
}

int UiTagWidth(const char *text) { return Measure(text, UI_XS, true) + 2 * PILL_PAD; }

int UiTag(const char *text, int x, int y, Color fill, Color ink)
{
    int w = UiTagWidth(text);
    Rectangle r = { (float)x, (float)y, (float)w, UI_PILL_H };
    // A dark rim keeps a light pill readable over a light sky
    Rounded((Rectangle){ r.x - 1, r.y - 1, r.width + 2, r.height + 2 }, UI_PILL_H / 2 + 1, (Color){ 0, 0, 0, 150 }, false);
    Rounded(r, UI_PILL_H / 2, fill, false);
    Text(text, x + PILL_PAD, y + UI_PILL_H / 2 - CapMiddle(UI_XS), UI_XS, true, ink);
    return w;
}

void UiToast(const char *text, int centreX, int y, int size, Color c, float alpha)
{
    int w = Measure(text, size, false), h = PixelSize(size) + 10;
    Rectangle r = { (float)(centreX - w / 2 - 14), (float)(y - 5), (float)(w + 28), (float)h };
    UiHalo(r, Mul(UI_HALO_C, alpha));
    Rounded(r, UI_RADIUS, Mul(UI_PANEL, alpha), false);
    Text(text, centreX - w / 2, y, size, false, Mul(c, alpha));
}

// #region Key hints

#define SEP_GAP     9   // space on each side of a | separator
#define CAP_PAD     4   // key cap: text to edge
#define CAP_MARGIN  2   // key cap: edge to the text around it

static int CapSize(int size) { return size >= UI_M ? size - 2 : UI_XS; }

// Offset from a line box's top to the middle of its capitals (Outfit: baseline 1000 and cap
// height 694 of the 1260 units the line box spans), for centring text in a box
static int CapMiddle(int size) { return (int)(PixelSize(size) * (1000.0f - 347.0f) / 1260.0f + 0.5f); }

// Key cap box (border colour c, fill CAP_FILL of it) for a line of `size`: the baked sprite's
// ends and its stretched middle
static void DrawCap(Rectangle r, int size, Color c)
{
    int i = 0;
    while (i < SIZE_COUNT && SIZES[i] != size) i++;
    if (!ui.ok || i == SIZE_COUNT || r.height != ui.cap[i].height || r.width < ui.cap[i].width) {
        Rounded(r, UI_CAP_R, c, false);
        return;
    }
    Rectangle s = ui.cap[i];
    float e = UI_CAP_R + 1;    // end width; the middle column is s.x + e
    DrawTexturePro(ui.atlas, (Rectangle){ s.x, s.y, e, s.height }, (Rectangle){ r.x, r.y, e, r.height }, (Vector2){ 0, 0 }, 0.0f, c);
    DrawTexturePro(ui.atlas, (Rectangle){ s.x + e, s.y, 1, s.height }, (Rectangle){ r.x + e, r.y, r.width - 2 * e, r.height },
                   (Vector2){ 0, 0 }, 0.0f, c);
    DrawTexturePro(ui.atlas, (Rectangle){ s.x + e + 1, s.y, e, s.height }, (Rectangle){ r.x + r.width - e, r.y, e, r.height },
                   (Vector2){ 0, 0 }, 0.0f, c);
}

// Draws (or only measures) one run of plain, dimmed, "on" or key-cap text; returns its width
static int Run(const char *s, int x, int y, int size, Color ink, bool cap, int tone, bool draw)
{
    if (!cap) {
        if (draw) Text(s, x, y, size, false, tone == '~' ? Mul(ink, 0.35f) : tone == '^' ? Mul(UI_HOT, ink.a / 255.0f) : ink);
        return Measure(s, size, false);
    }
    int cs = CapSize(size), bh = CapHeight(size);
    int w = Measure(s, cs, true) + 2 * CAP_PAD;
    if (draw) {
        // flat and dark: a faint white box, no border (the ink's alpha carries over)
        DrawCap((Rectangle){ (float)(x + CAP_MARGIN), (float)(y + 2), (float)w, (float)bh }, size, Mul(UI_RAISED, ink.a / 255.0f));
        Text(s, x + CAP_MARGIN + CAP_PAD, y + 2 + bh / 2 - CapMiddle(cs), cs, true, ink);
    }
    return w + 2 * CAP_MARGIN;
}

static int Hints(const char *s, int x, int y, int size, Color ink, bool draw)
{
    char run[256];      // one run of the markup (cut at 255 bytes)
    int n = 0, cx = x, lh = PixelSize(size);
    bool cap = false;
    int tone = 0;       // '~' dimmed, '^' on, 0 plain
    for (const char *p = s; ; p++) {
        char c = *p;
        if (c && c != '{' && c != '}' && c != '|' && c != '~' && c != '^') {
            if (n < (int)sizeof(run) - 1) run[n++] = c;
            continue;
        }
        if (n > 0) {
            run[n] = 0;
            cx += Run(run, cx, y, size, ink, cap, tone, draw);
            n = 0;
        }
        if (!c) break;
        if (c == '{') cap = true;
        else if (c == '}') cap = false;
        else if (c == '~' || c == '^') tone = tone == c ? 0 : c;
        else {
            if (draw) DrawRectangle(cx + SEP_GAP, y + lh / 4, 1, lh / 2, Mul(ink, 0.30f));
            cx += 2 * SEP_GAP + 1;
        }
    }
    return cx - x;
}

int UiHints(const char *markup, int x, int y, int size, Color ink) { return Hints(markup, x, y, size, ink, true); }
int UiHintsWidth(const char *markup, int size) { return Hints(markup, 0, 0, size, WHITE, false); }

// #endregion

#define BACKDROP_PAD 6

void UiHudText(const char *text, int x, int y, int h, int size, Color c)
{
    DrawRectangle(x - BACKDROP_PAD, y, Measure(text, size, false) + 2 * BACKDROP_PAD, h, UI_BACKDROP);
    Text(text, x, y + (h - PixelSize(size)) / 2, size, false, c);
}

void UiHudHints(const char *markup, int x, int y, int h, int size, Color ink)
{
    DrawRectangle(x - BACKDROP_PAD, y, UiHintsWidth(markup, size) + 2 * BACKDROP_PAD, h, UI_BACKDROP);
    UiHints(markup, x, y + (h - PixelSize(size)) / 2, size, ink);
}

int UiHudMark(const char *text, int x, int y, int h, int size, Color c)
{
    int w = MARK_BAR + MARK_GAP + Measure(text, size, false);
    DrawRectangle(x - BACKDROP_PAD, y, w + 2 * BACKDROP_PAD, h, UI_BACKDROP);
    DrawRectangle(x, y + 3, MARK_BAR, h - 6, c);
    Text(text, x + MARK_BAR + MARK_GAP, y + (h - PixelSize(size)) / 2, size, false, c);
    return w + 2 * BACKDROP_PAD;    // the next strip starts where this one ends
}

// #region The list widget (UiList; docs/live-editing.md 8.4)
// A panel's filterable list: the panel owns its items (any count; item i is just an index) and
// two callbacks, one that says whether item i passes the typed filter and one that draws its
// row. The widget keeps the selection, the scroll position, the filter text and the rows that
// pass it (heap arrays that only grow), and draws the settings panel's look around the rows.
// Use: UiListKeys each frame while the panel is open (then UiListRefilter if l->dirty or the
// items changed), UiListSelected for the item the panel's own keys act on, UiListDraw to draw,
// UiListFree when the panel goes away.

#define LIST_PAD        16      // panel edge to content
#define LIST_TITLE_H    42      // title line (UI_L bold)
#define LIST_FIELD_H    30      // the filter field
#define LIST_FOOTER_H   34      // the hints footer

static bool IsDown2(int a, int b) { return IsKeyDown(a) || IsKeyDown(b); }
static bool Pressed(int key) { return IsKeyPressed(key) || IsKeyPressedRepeat(key); }

void UiListKeys(UiList *l, int visibleRows)
{
    int page = visibleRows > 1 ? visibleRows - 1 : 1;
    int n = l->rowCount;
    if (n > 0) {
        if (Pressed(KEY_DOWN)) l->sel++;
        if (Pressed(KEY_UP)) l->sel--;
        if (Pressed(KEY_PAGE_DOWN)) l->sel += page;
        if (Pressed(KEY_PAGE_UP)) l->sel -= page;
        if (IsKeyPressed(KEY_HOME)) l->sel = 0;
        if (IsKeyPressed(KEY_END)) l->sel = n - 1;
        if (l->sel >= n) l->sel = n - 1;
        if (l->sel < 0) l->sel = 0;
    }
    // Typed characters (UTF-8) and BACKSPACE edit the filter
    for (int c = GetCharPressed(); c > 0; c = GetCharPressed()) {
        if (c < 32 || c == 127) continue;
        int len = 0;
        const char *u = CodepointToUTF8(c, &len);
        if (len <= 0 || !MS_RESERVE(l->filter, l->filterCap, l->filterLen + len + 1)) continue;
        memcpy(l->filter + l->filterLen, u, (size_t)len);
        l->filterLen += len;
        l->filter[l->filterLen] = 0;
        l->dirty = true;
    }
    if (Pressed(KEY_BACKSPACE) && l->filterLen > 0) {
        if (IsDown2(KEY_LEFT_CONTROL, KEY_RIGHT_CONTROL)) l->filterLen = 0;
        else {
            l->filterLen--;     // back to the start of the last UTF-8 sequence
            while (l->filterLen > 0 && ((unsigned char)l->filter[l->filterLen] & 0xC0) == 0x80) l->filterLen--;
        }
        l->filter[l->filterLen] = 0;
        l->dirty = true;
    }
}

bool UiListRefilter(UiList *l, int itemCount, UiListMatch match, void *user)
{
    int keep = UiListSelected(l);
    l->dirty = false;
    if (!MS_RESERVE(l->rows, l->rowCap, itemCount > 0 ? itemCount : 1)) {
        l->rowCount = l->sel = l->scroll = 0;
        return false;
    }
    bool filtering = l->filterLen > 0;
    int n = 0, sel = -1;
    for (int i = 0; i < itemCount; i++) {
        if (filtering && !match(i, l->filter, user)) continue;
        if (i == keep) sel = n;
        l->rows[n++] = i;
    }
    l->rowCount = n;
    if (sel >= 0) l->sel = sel;
    else if (l->sel >= n) l->sel = n > 0 ? n - 1 : 0;
    if (l->sel < 0) l->sel = 0;
    if (l->scroll > l->sel) l->scroll = l->sel;
    return true;
}

int UiListSelected(const UiList *l)
{
    return l->rows && l->sel >= 0 && l->sel < l->rowCount ? l->rows[l->sel] : -1;
}

int UiListDraw(UiList *l, Rectangle r, const char *title, int rowH, UiListDrawRow drawRow, void *user, const char *hints)
{
    if (rowH < 1) rowH = 24;
    int x = (int)r.x, y = (int)r.y, w = (int)r.width, h = (int)r.height;
    UiSheet(r);
    int tx = x + LIST_PAD, inner = w - 2 * LIST_PAD;
    UiTitle(title, tx, y + (LIST_TITLE_H - UI_TITLE_H) / 2 + 3, UI_INK);
    const char *count = TextFormat("%d", l->rowCount);
    UiText(count, x + w - LIST_PAD - UiMeasure(count, UI_S), y + (LIST_TITLE_H - UiLineHeight(UI_S)) / 2 + 5, UI_S, UI_DIM);

    // The filter field: the typed text and a cursor, or the placeholder
    Rectangle field = { (float)tx, (float)(y + LIST_TITLE_H), (float)inner, LIST_FIELD_H };
    UiPanel(field, UI_INSET, UI_LINE);
    int fy = (int)field.y + (LIST_FIELD_H - UiLineHeight(UI_M)) / 2;
    int fw = 0;
    if (l->filterLen > 0) {
        UiText(l->filter, tx + 10, fy, UI_M, UI_INK);
        fw = UiMeasure(l->filter, UI_M);
    } else UiText("type to filter", tx + 10, fy, UI_M, UI_FAINT);
    if (fmod(GetTime(), 1.0) < 0.6) DrawRectangle(tx + 10 + fw + 1, fy + 2, 2, UiLineHeight(UI_M) - 4, UI_HOT);

    // Rows: keep the selection visible
    int top = (int)field.y + LIST_FIELD_H + 10, bottom = y + h - LIST_FOOTER_H - 6;
    int visible = (bottom - top) / rowH;
    if (visible < 1) visible = 1;
    if (l->sel < l->scroll) l->scroll = l->sel;
    if (l->sel >= l->scroll + visible) l->scroll = l->sel - visible + 1;
    if (l->scroll > l->rowCount - visible) l->scroll = l->rowCount - visible;
    if (l->scroll < 0) l->scroll = 0;
    bool bar = l->rowCount > visible;
    int rowW = inner - (bar ? 10 : 0);
    for (int k = 0; k < visible && l->scroll + k < l->rowCount; k++) {
        int i = l->scroll + k;
        Rectangle row = { (float)tx, (float)(top + k * rowH), (float)rowW, (float)rowH };
        bool sel = i == l->sel;
        if (sel) {
            // square-edged, with the 2 px bar of a mark in white
            DrawRectangleRec(row, UI_ROW);
            DrawRectangle(tx, (int)row.y, 2, rowH, UI_HOT);
        }
        drawRow(l->rows[i], row, sel, user);
    }
    if (l->rowCount == 0)
        UiText(l->filterLen > 0 ? "nothing matches the filter" : "nothing to list", tx + 10, top + (rowH - UiLineHeight(UI_M)) / 2,
               UI_M, UI_DIM);
    if (bar) {
        // a thin track and a thumb of the visible share
        int trackH = visible * rowH;
        int thumbH = trackH * visible / l->rowCount;
        if (thumbH < 12) thumbH = 12;
        int thumbY = top + (trackH - thumbH) * l->scroll / (l->rowCount - visible);
        DrawRectangle(tx + inner - 3, top, 2, trackH, UI_LINE);
        DrawRectangle(tx + inner - 3, thumbY, 2, thumbH, UI_DIM);
    }

    int footY = y + h - LIST_FOOTER_H;
    DrawRectangle(tx, footY, inner, 1, UI_LINE);
    if (hints) UiHints(hints, tx, footY + (LIST_FOOTER_H - UiLineHeight(UI_XS)) / 2, UI_XS, UI_DIM);
    return visible;
}

void UiListClear(UiList *l)
{
    l->filterLen = 0;
    if (l->filter) l->filter[0] = 0;
    l->sel = l->scroll = 0;
    l->dirty = true;
}

void UiListFree(UiList *l)
{
    free(l->filter);
    free(l->rows);
    memset(l, 0, sizeof(*l));
}

// #endregion

// #region Mouse widgets (docs/painting.md 13.2)
// Immediate mode: every call lays out, handles and draws one widget. The state that outlives a
// frame is the caller's (UiDrag: the slider being dragged; UiEdit: the field being typed into,
// its text and cursor), named by the widget's id. A panel that reads its input before the frame
// is drawn runs its layout twice (UiWidgetsBegin: an input pass, then a draw pass). Fields take
// ASCII only (numbers, a hex colour); nothing here allocates.

#define WIDGET_FONT     UI_M
#define THUMB_W         10      // slider thumb
#define FIELD_PAD       7       // field edge to text
#define THUMB_D         12      // slider thumb: a disc

static struct {
    UiWidgetPass pass;
    bool noMouse;           // (all zero = the default: input and drawing, the mouse everywhere)
    Rectangle clip;
} wp;

void UiWidgetsBegin(UiWidgetPass pass, bool mouse, Rectangle clip)
{
    wp.pass = pass;
    wp.noMouse = !mouse;
    wp.clip = clip;
}

void UiWidgetsEnd(void) { memset(&wp, 0, sizeof(wp)); }

static bool WInput(void) { return wp.pass != UI_WIDGETS_DRAW; }
static bool WDraw(void) { return wp.pass != UI_WIDGETS_INPUT; }
static bool WMouse(void) { return !wp.noMouse; }

static bool WHover(Rectangle r)
{
    if (wp.noMouse) return false;
    Vector2 m = GetMousePosition();
    if (wp.clip.width > 0.0f && !CheckCollisionPointRec(m, wp.clip)) return false;
    return CheckCollisionPointRec(m, r);
}

static bool WPressed(void) { return WInput() && WMouse() && IsMouseButtonPressed(MOUSE_BUTTON_LEFT); }

// UI_M, or UI_S when the text doesn't fit in w
static int FitSize(const char *text, int w)
{
    return Measure(text, WIDGET_FONT, false) <= w ? WIDGET_FONT : UI_S;
}

void UiRoundRect(Rectangle r, int radius, Color fill, Color border)
{
    if (fill.a) Rounded(r, radius, fill, false);
    if (border.a) Rounded(r, radius, border, true);
}

static float Snap(float v, float lo, float hi, float step)
{
    if (step > 0.0f) v = lo + roundf((v - lo) / step) * step;
    return v < lo ? lo : v > hi ? hi : v;
}

bool UiSlider(UiDrag *drag, int id, Rectangle r, float *value, float lo, float hi, float step)
{
    float x0 = r.x + THUMB_W / 2, x1 = r.x + r.width - THUMB_W / 2, span = x1 - x0 > 1.0f ? x1 - x0 : 1.0f;
    float range = hi > lo ? hi - lo : 1.0f;
    float old = *value, v = old;
    bool hover = WHover(r);
    if (WInput()) {
        Vector2 m = GetMousePosition();
        float thumbX = x0 + (Snap(v, lo, hi, 0.0f) - lo) / range * span;
        if (drag->active == id) {
            if (WMouse() && IsMouseButtonDown(MOUSE_BUTTON_LEFT)) v = lo + (m.x - drag->grab - x0) / span * range;
            else drag->active = 0;
        } else if (drag->active == 0 && hover && WPressed()) {
            drag->active = id;
            // on the thumb: it keeps its offset to the cursor; elsewhere it jumps there
            drag->grab = fabsf(m.x - thumbX) <= THUMB_W / 2 + 1 ? m.x - thumbX : 0.0f;
            v = lo + (m.x - drag->grab - x0) / span * range;
        }
        float wheel = hover && (drag->active == 0 || drag->active == id) ? GetMouseWheelMove() : 0.0f;
        if (wheel != 0.0f) v += (wheel > 0.0f ? 1.0f : -1.0f) * (step > 0.0f ? step : range / 50.0f);
        if (v != old) *value = Snap(v, lo, hi, step);
    }
    if (WDraw()) {
        bool held = drag->active == id;
        float t = (Snap(*value, lo, hi, 0.0f) - lo) / range;
        int cy = (int)(r.y + r.height / 2);
        int tx = (int)(x0 + t * span + 0.5f);
        // a 2 px track, its filled part white, a white disc that glows while held
        DrawRectangle((int)r.x, cy - 1, (int)r.width, 2, UI_LINE);
        if (tx > (int)r.x) DrawRectangle((int)r.x, cy - 1, tx - (int)r.x, 2, UI_DIM);
        Rectangle thumb = { (float)(tx - THUMB_D / 2), (float)(cy - THUMB_D / 2), THUMB_D, THUMB_D };
        if (held) UiHalo(thumb, Mul(UI_HOT, 0.45f));
        Rounded(thumb, THUMB_D / 2, held || hover ? UI_HOT : UI_INK, false);
    }
    return *value != old;
}

// Opens field id with text (all selected)
static void EditOpen(UiEdit *e, int id, const char *text)
{
    e->active = id;
    e->claim = 0;
    snprintf(e->buf, sizeof(e->buf), "%s", text);
    e->len = (int)strlen(e->buf);
    e->cursor = e->len;
    e->all = e->len > 0;
}

// The open field's keys and typed characters: 1 ENTER, -1 ESC, 0 still typing. accept: the
// characters it takes (NULL: any printable ASCII); max: the longest text
static int EditKeys(UiEdit *e, const char *accept, int max)
{
    if (max > (int)sizeof(e->buf) - 1) max = (int)sizeof(e->buf) - 1;
    for (int c = GetCharPressed(); c > 0; c = GetCharPressed()) {
        if (c < 32 || c > 126 || (accept && !strchr(accept, c))) continue;
        if (e->all) { e->len = e->cursor = 0; e->all = false; }
        if (e->len >= max) continue;
        memmove(e->buf + e->cursor + 1, e->buf + e->cursor, (size_t)(e->len - e->cursor));
        e->buf[e->cursor++] = (char)c;
        e->buf[++e->len] = 0;
    }
    if (Pressed(KEY_BACKSPACE)) {
        if (e->all) { e->len = e->cursor = 0; e->all = false; }
        else if (e->cursor > 0) {
            memmove(e->buf + e->cursor - 1, e->buf + e->cursor, (size_t)(e->len - e->cursor));
            e->cursor--;
            e->len--;
        }
        e->buf[e->len] = 0;
    }
    if (Pressed(KEY_DELETE)) {
        if (e->all) { e->len = e->cursor = 0; e->all = false; }
        else if (e->cursor < e->len) {
            memmove(e->buf + e->cursor, e->buf + e->cursor + 1, (size_t)(e->len - e->cursor - 1));
            e->len--;
        }
        e->buf[e->len] = 0;
    }
    if (Pressed(KEY_LEFT)) { e->cursor = e->all ? 0 : e->cursor > 0 ? e->cursor - 1 : 0; e->all = false; }
    if (Pressed(KEY_RIGHT)) { e->cursor = e->all ? e->len : e->cursor < e->len ? e->cursor + 1 : e->len; e->all = false; }
    if (IsKeyPressed(KEY_HOME)) { e->cursor = 0; e->all = false; }
    if (IsKeyPressed(KEY_END)) { e->cursor = e->len; e->all = false; }
    if (IsKeyPressed(KEY_A) && IsDown2(KEY_LEFT_CONTROL, KEY_RIGHT_CONTROL)) e->all = e->len > 0;
    if (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_KP_ENTER)) return 1;
    if (IsKeyPressed(KEY_ESCAPE)) return -1;
    return 0;
}

// What a field does this frame: 1 apply, -1 cancel (it closed), 0 nothing (or still typing). A
// click on it opens it with `shown`; with another field open, that one applies on the same
// click (it sees a click elsewhere) and this one opens the next frame, in either call order.
static int FieldInput(UiEdit *e, int id, Rectangle r, const char *shown, const char *accept, int max)
{
    if (!WInput()) return 0;
    if (e->claim == id && e->active == 0) EditOpen(e, id, shown);
    if (e->active == id) {
        if (WPressed() && !WHover(r)) { e->active = 0; return 1; }
        int k = EditKeys(e, accept, max);
        if (k) e->active = 0;
        return k;
    }
    if (WPressed() && WHover(r)) {
        if (e->active == 0) EditOpen(e, id, shown);
        else e->claim = id;
    }
    return 0;
}

// The field's box and its text: while open the typed text with the cursor (or the selection),
// else `shown`, centred
static void FieldDraw(const UiEdit *e, int id, Rectangle r, const char *shown, Color ink)
{
    bool open = e->active == id, hover = WHover(r);
    UiPanel(r, UI_INSET, open ? UI_DIM : hover ? UI_FAINT : UI_LINE);
    const char *text = open ? e->buf : shown;
    int size = FitSize(text, (int)r.width - 2 * FIELD_PAD);
    int lh = UiLineHeight(size);
    int ty = (int)r.y + ((int)r.height - lh) / 2;
    int tw = Measure(text, size, false);
    int tx = open ? (int)r.x + FIELD_PAD : (int)(r.x + (r.width - tw) / 2);
    if (open && e->all && e->len > 0) DrawRectangle(tx - 1, ty + 2, tw + 2, lh - 4, UI_SELECT);
    if (text[0]) Text(text, tx, ty, size, false, open ? UI_INK : ink);
    if (open && !e->all && fmod(GetTime(), 1.0) < 0.6) {
        char head[32];
        snprintf(head, sizeof(head), "%.*s", e->cursor, e->buf);
        DrawRectangle(tx + Measure(head, size, false), ty + 2, 2, lh - 4, UI_HOT);
    }
}

static void FormatNumber(char *out, int outSize, float v, int decimals)
{
    if (decimals <= 0) snprintf(out, (size_t)outSize, "%d", (int)roundf(v));
    else snprintf(out, (size_t)outSize, "%.*f", decimals, v);
}

bool UiNumberField(UiEdit *edit, int id, Rectangle r, float *value, float lo, float hi, float step, int decimals)
{
    char shown[32];
    FormatNumber(shown, sizeof(shown), *value, decimals);
    float old = *value;
    if (FieldInput(edit, id, r, shown, "0123456789.-+", 12) == 1 && edit->len > 0) {
        char *end = NULL;
        float v = strtof(edit->buf, &end);
        if (end != edit->buf && isfinite(v)) {
            float scale = powf(10.0f, (float)(decimals > 0 ? decimals : 0));
            v = roundf(v * scale) / scale;
            *value = v < lo ? lo : v > hi ? hi : v;
        }
    }
    if (WInput() && edit->active != id && WHover(r)) {
        float wheel = GetMouseWheelMove();
        float s = step > 0.0f ? step : 1.0f;
        if (wheel != 0.0f) *value = Snap(*value + (wheel > 0.0f ? s : -s), lo, hi, 0.0f);
    }
    if (WDraw()) {
        FormatNumber(shown, sizeof(shown), *value, decimals);
        FieldDraw(edit, id, r, shown, UI_INK);
    }
    return *value != old;
}

bool UiTextField(UiEdit *edit, int id, Rectangle r, char *text, int textSize)
{
    bool applied = false;
    if (FieldInput(edit, id, r, text, NULL, textSize - 1) == 1) {
        snprintf(text, (size_t)textSize, "%s", edit->buf);
        applied = true;
    }
    if (WDraw()) FieldDraw(edit, id, r, text, UI_INK);
    return applied;
}

bool UiSwatch(Rectangle r, Color c, bool selected)
{
    bool hover = WHover(r);
    if (WDraw()) {
        if (c.a < 255) {
            // the checker the alpha shows over: 6 px squares, cut at the swatch's edges
            const int q = 6;
            DrawRectangleRec(r, (Color){ 205, 205, 205, 255 });
            for (int yy = 0; yy * q < (int)r.height; yy++)
                for (int xx = yy & 1; xx * q < (int)r.width; xx += 2) {
                    float w = fminf((float)q, r.width - (float)(xx * q)), h = fminf((float)q, r.height - (float)(yy * q));
                    DrawRectangleRec((Rectangle){ r.x + (float)(xx * q), r.y + (float)(yy * q), w, h }, (Color){ 125, 125, 125, 255 });
                }
        }
        DrawRectangleRec(r, c);
        if (selected) DrawRectangleLinesEx((Rectangle){ r.x - 2, r.y - 2, r.width + 4, r.height + 4 }, 2.0f, UI_HOT);
        else DrawRectangleLinesEx(r, 1.0f, hover ? UI_DIM : UI_LINE);
    }
    return hover && WPressed();
}

bool UiButton(Rectangle r, const char *label, bool active)
{
    bool hover = WHover(r);
    if (WDraw()) {
        bool held = hover && IsMouseButtonDown(MOUSE_BUTTON_LEFT);
        // flat white-alpha; on (or held): white with black text
        bool on = active || held;
        Rounded(r, UI_RADIUS, on ? UI_INK : hover ? UI_HOVER : UI_RAISED, false);
        if (label && label[0]) {
            int size = FitSize(label, (int)r.width - 8);
            int tw = Measure(label, size, false);
            Text(label, (int)(r.x + (r.width - tw) / 2), (int)r.y + ((int)r.height - UiLineHeight(size)) / 2, size, false,
                 on ? UI_ON_INK : hover ? UI_HOT : UI_INK);
        }
    }
    return hover && WPressed();
}

bool UiWidgetsBusy(const UiDrag *drag, const UiEdit *edit)
{
    return (drag && drag->active) || (edit && (edit->active || edit->claim));
}

// #endregion
